package local.skyfamily;
import java.net.*;import java.io.*;import org.json.JSONObject;
final class WeatherHttp {
 static boolean handles(URL url){return url.getHost().equalsIgnoreCase("api.open-meteo.com")||url.getHost().equalsIgnoreCase("geocoding-api.open-meteo.com");}
 static String stage(URL url){return url.getHost().equalsIgnoreCase("api.open-meteo.com")?"forecast":"location search";}
 static byte[] read(InputStream input,int limit)throws Exception{if(input==null)return new byte[0];try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int size;while((size=in.read(buffer))!=-1){if(out.size()+size>limit)throw new IOException("Weather response exceeds size limit");out.write(buffer,0,size);}return out.toByteArray();}}
 static byte[] get(URL url,int limit)throws Exception{if(!handles(url)||!url.getProtocol().equals("https")||url.getUserInfo()!=null||(url.getPort()!=-1&&url.getPort()!=443))throw new IOException("Weather requires its official HTTPS endpoint");HttpURLConnection connection=(HttpURLConnection)url.openConnection();connection.setRequestMethod("GET");connection.setConnectTimeout(15000);connection.setReadTimeout(25000);connection.setInstanceFollowRedirects(false);connection.setRequestProperty("Accept","application/json");connection.setRequestProperty("User-Agent","SkyFamily/0.11.0-alpha (Android; personal weather display)");try{int code=connection.getResponseCode();if(code>=200&&code<300){byte[] bytes=read(connection.getInputStream(),limit);JSONObject body=new JSONObject(new String(bytes,"UTF-8"));if(body.optBoolean("error"))throw new IOException("Open-Meteo "+stage(url)+": "+body.optString("reason","provider error"));return bytes;}String reason="";try{JSONObject error=new JSONObject(new String(read(connection.getErrorStream(),4096),"UTF-8"));reason=error.optString("reason",error.optString("message",""));reason=reason.replaceAll("[\\r\\n\\t]+"," ");if(reason.length()>220)reason=reason.substring(0,220);}catch(Exception ignored){}String help=code==403?"Request denied by provider or network. An Immich login will not fix this. Check this frame's network filtering and provider access.":code==429?"Provider rate limit. Wait before retrying.":code>=300&&code<400?"Unexpected redirect; not followed for weather.":"Weather service request failed.";throw new IOException("Open-Meteo "+stage(url)+" HTTP "+code+". "+help+(reason.isEmpty()?"":" Provider: "+reason));}finally{connection.disconnect();}}
}
